+ 
+   const {inheritanceGraph} = executeAnalysisPhase(host, knownInputs, result, analysisDeps);
+ 
+   // Populate from batch metadata.
+   for (const [_key, info] of Object.entries(mergedMetadata.knownInputs)) {
