+  * ```
+  */
+ function assertSafeToImmutablyUpdate(obj: {}): void {
+   // `new MyClass()` case.
+   if (obj.constructor !== Object) {
+     throw new Error(`Cannot immutably update type: ${obj.constructor.name}`);
+   }
