+     } else if (propertyType.flags & ts.TypeFlags.String) {
+       typeToAdd = ts.factory.createKeywordTypeNode(ts.SyntaxKind.StringKeyword);
+     } else if (propertyType.flags & ts.TypeFlags.Number) {
